import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val _A = 'a'
private const val _B = 'b'
private const val _C = 'c'

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val n = st.nextToken().toInt()
    val k = st.nextToken().toInt()
    val s = reader.readLine()
    val t = reader.readLine()
    val result = find_best_score_can_make(s, t, moves_n = k)
    println(result)
}

fun find_best_score_can_make(s: String, t: String, moves_n: Int): Long {
    require(t.length == 2)
    if (t[0] == t[1]) {
        val tChar = t[0]
        var tCharCount = s.count { it == tChar }
        tCharCount += moves_n
        if (tCharCount > s.length) {
            tCharCount = s.length
        }
        return tCharCount.toLong() * (tCharCount - 1).toLong() / 2L
    }

    val mapped = CharArray(s.length) { i ->
        val ch = s[i]
        if (ch == t[0] || ch == t[1]) {
            if (t.indexOf(ch) == 0) _A else _B
        } else {
            _C
        }
    }
    val newS = String(mapped)

    val (aIndices, bIndices, cIndices) = _compute_abc_indices(newS)

    var bestScore = Long.MIN_VALUE

    val maxCStart = minOf(cIndices.size, moves_n)
    for (cStart in 0..maxCStart) {
        val cStartMovesSpent = cStart
        var movesSpent = cStartMovesSpent
        var movesRemain = moves_n - movesSpent
        require(movesRemain >= 0)

        val maxBStart = minOf(bIndices.size, movesRemain)
        for (bStart in 0..maxBStart) {
            val bStartMovesSpent = bStart
            movesSpent = cStartMovesSpent + bStartMovesSpent
            movesRemain = moves_n - movesSpent
            require(movesRemain >= 0)

            val currS = newS.toCharArray()
            for (iIc in 0 until cStart) {
                val iC = cIndices[iIc]
                currS[iC] = _A
            }
            for (iIb in 0 until bStart) {
                val iB = bIndices[iIb]
                currS[iB] = _A
            }

            val currBestScore = _find_best_score_can_make_with_fixed_starts(String(currS), movesRemain)
            if (currBestScore > bestScore) {
                bestScore = currBestScore
            }
        }
    }

    return bestScore
}

data class IndicesTriple(
    val aIndices: IntArray,
    val bIndices: IntArray,
    val cIndices: IntArray
)

fun _compute_abc_indices(s: String): IndicesTriple {
    val aList = ArrayList<Int>()
    val bList = ArrayList<Int>()
    val cList = ArrayList<Int>()
    for (iChar in s.indices) {
        val char = s[iChar]
        when (char) {
            _A -> aList.add(iChar)
            _B -> bList.add(iChar)
            else -> {
                require(char == _C)
                cList.add(iChar)
            }
        }
    }
    return IndicesTriple(
        aList.toIntArray(),
        bList.toIntArray(),
        cList.toIntArray()
    )
}

fun _find_best_score_can_make_with_fixed_starts(s: String, moves_n: Int): Long {
    val sArr = s.toCharArray()

    var bestScore = Long.MIN_VALUE

    val (aIndices, _, cIndices) = _compute_abc_indices(String(sArr))

    val aN = aIndices.size
    val cN = cIndices.size

    val maxAStop = aIndices.size
    val maxCStop = cIndices.size

    fun get_c_stop_by_moves_remain(movesRemain: Int): Int {
        var minCStop = maxCStop - movesRemain
        if (minCStop < 0) {
            minCStop = 0
        }
        val cStop = minCStop
        return cStop
    }

    val firstCStop = get_c_stop_by_moves_remain(moves_n)
    val newS = _get_curr_s(String(sArr), aIndices, maxAStop, cIndices, firstCStop)
    var currScore = _get_curr_score_slow_way(newS)

    if (currScore > bestScore) {
        bestScore = currScore
    }

    val oldABefore = _compute_a_before(String(newS))
    val oldBAfterIfAllCAreB = _compute_b_after(String(newS).replace(_C, _B))

    var currBToCBeforeA = 0
    var currAToBAfterC = 0

    var prevCStop: Int? = null
    var cStop = firstCStop
    var cStopMovesSpent = maxCStop - cStop

    var minAStop = maxAStop - moves_n
    minAStop = maxOf(minAStop, 0)
    for (aStop in maxAStop - 1 downTo minAStop) {
        val aStopMovesSpent = maxAStop - aStop
        val movesSpent = aStopMovesSpent
        val movesRemain = moves_n - movesSpent
        require(movesRemain >= 0)

        require(aStopMovesSpent > 0)

        val currAIndex = aIndices[aStop]
        val currBToC = cStop
        if (currBToCBeforeA < currBToC && cIndices[currBToCBeforeA] < currAIndex) {
            while (currBToCBeforeA < currBToC && cIndices[currBToCBeforeA] < currAIndex) {
                currBToCBeforeA += 1
            }
        } else if (currBToCBeforeA > 0 && cIndices[currBToCBeforeA - 1] > currAIndex) {
            while (currBToCBeforeA > 0 && cIndices[currBToCBeforeA - 1] > currAIndex) {
                currBToCBeforeA -= 1
            }
        }

        val prevAStopMovesSpent = aStopMovesSpent - 1
        val currBToCAfterA = currBToC - currBToCBeforeA
        val newBAfter = prevAStopMovesSpent - currBToCAfterA
        val bAfter = oldBAfterIfAllCAreB[currAIndex] + newBAfter
        currScore -= bAfter.toLong()
        currScore += oldABefore[currAIndex].toLong()

        prevCStop = cStop
        cStop = get_c_stop_by_moves_remain(movesRemain)
        cStopMovesSpent = maxCStop - cStop

        require(cStop - prevCStop in 0..1)
        if (cStop - prevCStop == 1) {
            val prevCIndex = cIndices[prevCStop]
            val currAToB = aN - aStop
            if (currAToBAfterC < currAToB && aIndices[aN - (currAToBAfterC + 1)] > prevCIndex) {
                while (currAToBAfterC < currAToB && aIndices[aN - (currAToBAfterC + 1)] > prevCIndex) {
                    currAToBAfterC += 1
                }
            } else if (currAToBAfterC > 0 && aIndices[aN - currAToBAfterC] < prevCIndex) {
                while (currAToBAfterC > 0 && aIndices[aN - currAToBAfterC] < prevCIndex) {
                    currAToBAfterC -= 1
                }
            }

            val aToBBefore = currAToB - currAToBAfterC
            val currABefore = oldABefore[prevCIndex] - aToBBefore
            currScore -= currABefore.toLong()
        }

        if (currScore > bestScore) {
            bestScore = currScore
        }
    }

    return bestScore
}

fun _get_curr_s(
    s: String,
    aIndices: IntArray,
    aStop: Int,
    cIndices: IntArray,
    cStop: Int
): CharArray {
    val arr = s.toCharArray()
    for (iIa in 0 until aStop) {
        val iA = aIndices[iIa]
        arr[iA] = _A
    }
    for (iIa in aStop until aIndices.size) {
        val iA = aIndices[iIa]
        arr[iA] = _B
    }
    for (iIc in 0 until cStop) {
        val iC = cIndices[iIc]
        arr[iC] = _C
    }
    for (iIc in cStop until cIndices.size) {
        val iC = cIndices[iIc]
        arr[iC] = _B
    }
    return arr
}

fun _get_curr_score_slow_way(s: CharArray): Long {
    var currScore = 0L
    var aAccumulated = 0L
    for (char in s) {
        when (char) {
            _A -> aAccumulated += 1
            _B -> currScore += aAccumulated
        }
    }
    return currScore
}

fun _compute_a_before(s: String): IntArray {
    val n = s.length
    val result = IntArray(n + 1)
    var acc = 0
    for (i in 0 until n) {
        acc += if (s[i] == _A) 1 else 0
        result[i + 1] = acc
    }
    val shifted = IntArray(n)
    for (i in 0 until n) {
        shifted[i] = result[i]
    }
    return shifted
}

fun _compute_b_after(s: String): IntArray {
    val n = s.length
    val revAcc = IntArray(n)
    var acc = 0
    for (i in n - 1 downTo 0) {
        acc += if (s[i] == _B) 1 else 0
        revAcc[i] = acc
    }
    val result = IntArray(n)
    for (i in 0 until n) {
        result[i] = revAcc[i]
    }
    val shifted = IntArray(n)
    for (i in 0 until n - 1) {
        shifted[i] = result[i + 1]
    }
    shifted[n - 1] = 0
    return shifted
}

