    val (aIndicesArr, bIndicesArr, cIndicesArr) = _compute_abc_indices(String(s))
    val aIndices = aIndicesArr
    val cIndices = cIndicesArr

    val a_n = aIndices.size
    val c_n = cIndices.size

    val max_a_stop = aIndices.size
    val max_c_stop = cIndices.size

    fun get_c_stop_by_moves_remain(movesRemain: Int): Int {
        var min_c_stop = max_c_stop - movesRemain
        if (min_c_stop < 0) {
            min_c_stop = 0
        }
