    val first_c_stop = get_c_stop_by_moves_remain(moves_n)
    val new_s = _get_curr_s(s, aIndices, max_a_stop, cIndices, first_c_stop)
    var curr_score = _get_curr_score_slow_way(new_s)

    if (curr_score > bestScore) {
        bestScore = curr_score
    }

