    var c_stop = first_c_stop
    var c_stop_moves_spent = max_c_stop - c_stop

    var min_a_stop = max_a_stop - moves_n
    min_a_stop = maxOf(min_a_stop, 0)
    for (a_stop in max_a_stop - 1 downTo min_a_stop) {
