        c_stop = get_c_stop_by_moves_remain(moves_remain)
        c_stop_moves_spent = max_c_stop - c_stop

        require(c_stop - prev_c_stop in 0..1)
        if (c_stop - prev_c_stop == 1) {
            val prev_c_index = cIndices[prev_c_stop]
            val curr_a_to_b = a_n - a_stop
            if (curr_a_to_b_after_c < curr_a_to_b &&
                aIndices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index
