            tCharCount = sInput.length
        }
        return tCharCount.toLong() * (tCharCount - 1).toLong() / 2L
    }

    val mapped = CharArray(sInput.length) { i ->
        val ch = sInput[i]
        if (ch == t[0]) _A
        else if (ch == t[1]) _B
        else _C
    }
    val s = String(mapped)

    val (aIndices, bIndices, cIndices) = computeAbcIndices(s)

    var bestScore = Long.MIN_VALUE

    val max_c_start = minOf(cIndices.size, moves_n)
    for (c_start in 0..max_c_start) {
        val c_start_moves_spent = c_start
