            for (i_i_b in 0 until b_start) {
                val i_b = bIndices[i_i_b]
                new_s[i_b] = _A
            }

            val curr_best_score = findBestScoreCanMakeWithFixedStarts(new_s, moves_remain)
            if (curr_best_score > bestScore) {
                bestScore = curr_best_score
            }
        }
    }

    return bestScore
}

