    var c_stop_moves_spent = max_c_stop - c_stop

    var min_a_stop = max_a_stop - moves_n
    min_a_stop = maxOf(min_a_stop, 0)
    for (a_stop in (min_a_stop..(max_a_stop - 1)).reversed()) {
        val a_stop_moves_spent = max_a_stop - a_stop
        var moves_spent = a_stop_moves_spent
        val moves_remain = moves_n - moves_spent
        require(moves_remain >= 0)

        require(a_stop_moves_spent > 0)

        val curr_a_index = aIndices[a_stop]
        val curr_b_to_c = c_stop
        if (curr_b_to_c_before_a < curr_b_to_c &&
            cIndices[curr_b_to_c_before_a] < curr_a_index
        ) {
            while (curr_b_to_c_before_a < curr_b_to_c &&
                cIndices[curr_b_to_c_before_a] < curr_a_index
            ) {
                curr_b_to_c_before_a += 1
            }
        } else if (curr_b_to_c_before_a > 0 &&
            cIndices[curr_b_to_c_before_a - 1] > curr_a_index
        ) {
            while (curr_b_to_c_before_a > 0 &&
                cIndices[curr_b_to_c_before_a - 1] > curr_a_index
            ) {
                curr_b_to_c_before_a -= 1
            }
        }

        val prev_a_stop_moves_spent = a_stop_moves_spent - 1
        val curr_b_to_c_after_a = curr_b_to_c - curr_b_to_c_before_a
        val new_b_after = prev_a_stop_moves_spent - curr_b_to_c_after_a
        val b_after = old_b_after_if_all_c_are_b[curr_a_index] + new_b_after
        curr_score -= b_after.toLong()
        curr_score += old_a_before[curr_a_index].toLong()

        prev_c_stop = c_stop
        c_stop = get_c_stop_by_moves_remain(moves_remain)
        c_stop_moves_spent = max_c_stop - c_stop

        require(c_stop - prev_c_stop in listOf(0, 1))
        if (c_stop - prev_c_stop == 1) {
            val prev_c_index = cIndices[prev_c_stop]
            val curr_a_to_b = a_n - a_stop
            if (curr_a_to_b_after_c < curr_a_to_b &&
                aIndices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index
            ) {
                while (curr_a_to_b_after_c < curr_a_to_b &&
                    aIndices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index
                ) {
                    curr_a_to_b_after_c += 1
                }
            } else if (curr_a_to_b_after_c > 0 &&
                aIndices[a_n - curr_a_to_b_after_c] < prev_c_index
            ) {
                while (curr_a_to_b_after_c > 0 &&
                    aIndices[a_n - curr_a_to_b_after_c] < prev_c_index
                ) {
                    curr_a_to_b_after_c -= 1
                }
            }

            val a_to_b_before = curr_a_to_b - curr_a_to_b_after_c
            val curr_a_before = old_a_before[prev_c_index] - a_to_b_before
            curr_score -= curr_a_before.toLong()
        }

        if (curr_score > bestScore) {
            bestScore = curr_score
        }
    }

    return bestScore
}

fun getCurrS(
    sInput: CharArray,
    aIndices: IntArray,
    a_stop: Int,
    cIndices: IntArray,
    c_stop: Int
): CharArray {
    val s = sInput.copyOf()
    for (i_i_a in 0 until a_stop) {
        val i_a = aIndices[i_i_a]
        s[i_a] = _A
    }
    for (i_i_a in a_stop until aIndices.size) {
        val i_a = aIndices[i_i_a]
        s[i_a] = _B
    }
    for (i_i_c in 0 until c_stop) {
        val i_c = cIndices[i_i_c]
        s[i_c] = _C
    }
    for (i_i_c in c_stop until cIndices.size) {
        val i_c = cIndices[i_i_c]
        s[i_c] = _B
    }
    return s
}

fun getCurrScoreSlowWay(s: CharArray): Long {
    var curr_score = 0L
    var a_accumulated = 0L
    for (char in s) {
        when (char) {
            _A -> a_accumulated += 1
            _B -> curr_score += a_accumulated
        }
    }
    return curr_score
}

fun computeABefore(sInput: CharArray): IntArray {
    val n = sInput.size
    val result = IntArray(n + 1)
    var acc = 0
    for (i in 0 until n) {
        acc += if (sInput[i] == _A) 1 else 0
        result[i + 1] = acc
    }
    val finalRes = IntArray(n)
    for (i in 0 until n) {
        finalRes[i] = result[i]
    }
    return finalRes
}

fun computeBAfter(sInput: String): IntArray {
    val n = sInput.length
    val revAcc = IntArray(n)
    var acc = 0
    for (i in n - 1 downTo 0) {
        acc += if (sInput[i] == _B) 1 else 0
        revAcc[i] = acc
    }
    val result = IntArray(n)
    for (i in 0 until n) {
        result[i] = revAcc[i]
    }
    val finalRes = IntArray(n)
    for (i in 0 until n - 1) {
        finalRes[i] = result[i + 1]
    }
    finalRes[n - 1] = 0
    return finalRes
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val _A = 'a'
private const val _B = 'b'
private const val _C = 'c'

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val n = st.nextToken().toInt()
    val k = st.nextToken().toInt()
    val s = reader.readLine()
    val t = reader.readLine()
    val result = findBestScoreCanMake(s, t, moves_n = k)
    println(result)
}

fun findBestScoreCanMake(s: String, t: String, moves_n: Int): Long {
    require(t.length == 2)
    if (t[0] == t[1]) {
        val tChar = t[0]
        var tCharCount = s.count { it == tChar }
        tCharCount += moves_n
        if (tCharCount > s.length) {
            tCharCount = s.length
        }
        return tCharCount.toLong() * (tCharCount - 1) / 2
    }

    val mapped = CharArray(s.length) { i ->
        val ch = s[i]
        if (ch == t[0]) _A
        else if (ch == t[1]) _B
        else _C
    }
    val newS = String(mapped)

    val (aIndices, bIndices, cIndices) = computeAbcIndices(newS)

    var bestScore = Long.MIN_VALUE

    val maxCStart = minOf(cIndices.size, moves_n)
    for (cStart in 0..maxCStart) {
        val cStartMovesSpent = cStart
        var movesSpent = cStartMovesSpent
        var movesRemain = moves_n - movesSpent
        require(movesRemain >= 0)

        val maxBStart = minOf(bIndices.size, movesRemain)
        for (bStart in 0..maxBStart) {
            val bStartMovesSpent = bStart
            movesSpent = cStartMovesSpent + bStartMovesSpent
            movesRemain = moves_n - movesSpent
            require(movesRemain >= 0)

            val currS = newS.toCharArray()
            for (iIc in 0 until cStart) {
                val iC = cIndices[iIc]
                currS[iC] = _A
            }
            for (iIb in 0 until bStart) {
                val iB = bIndices[iIb]
                currS[iB] = _A
            }

            val currBestScore = findBestScoreCanMakeWithFixedStarts(currS, movesRemain)
            if (currBestScore > bestScore) {
                bestScore = currBestScore
            }
        }
    }

    return bestScore
}

data class IndicesTriple(
    val aIndices: IntArray,
    val bIndices: IntArray,
    val cIndices: IntArray
)

fun computeAbcIndices(s: String): IndicesTriple {
    val aList = ArrayList<Int>()
    val bList = ArrayList<Int>()
    val cList = ArrayList<Int>()
    for ((i, ch) in s.withIndex()) {
        when (ch) {
            _A -> aList.add(i)
            _B -> bList.add(i)
            else -> {
                require(ch == _C)
                cList.add(i)
            }
        }
    }
    return IndicesTriple(
        aList.toIntArray(),
        bList.toIntArray(),
        cList.toIntArray()
    )
}

fun findBestScoreCanMakeWithFixedStarts(sArr: CharArray, moves_n: Int): Long {
    val s = sArr.copyOf()

    var bestScore = Long.MIN_VALUE

    val (aIndicesArr, _, cIndicesArr) = computeAbcIndices(String(s))

    val aIndices = aIndicesArr
    val cIndices = cIndicesArr

    val a_n = aIndices.size
    val c_n = cIndices.size

    val max_a_stop = aIndices.size
    val max_c_stop = cIndices.size

    fun get_c_stop_by_moves_remain(movesRemain: Int): Int {
        var min_c_stop = max_c_stop - movesRemain
        if (min_c_stop < 0) {
            min_c_stop = 0
        }
        return min_c_stop
    }

    val first_c_stop = get_c_stop_by_moves_remain(moves_n)
    val new_s = getCurrS(s, aIndices, max_a_stop, cIndices, first_c_stop)
    var curr_score = getCurrScoreSlowWay(new_s)

    if (curr_score > bestScore) {
        bestScore = curr_score
    }

    val old_a_before = computeABefore(new_s)
    val replaced = String(new_s).replace(_C, _B)
    val old_b_after_if_all_c_are_b = computeBAfter(replaced)

    var curr_b_to_c_before_a = 0
    var curr_a_to_b_after_c = 0

    var prev_c_stop: Int? = null
    var c_stop = first_c_stop
    var c_stop_moves_spent = max_c_stop - c_stop

    var min_a_stop = max_a_stop - moves_n
    min_a_stop = maxOf(min_a_stop, 0)
    for (a_stop in (min_a_stop..(max_a_stop - 1)).reversed()) {
        val a_stop_moves_spent = max_a_stop - a_stop
        var movesSpent = a_stop_moves_spent
        val movesRemain = moves_n - movesSpent
        require(movesRemain >= 0)

        require(a_stop_moves_spent > 0)

        val curr_a_index = aIndices[a_stop]
        val curr_b_to_c = c_stop
        if (curr_b_to_c_before_a < curr_b_to_c &&
            cIndices[curr_b_to_c_before_a] < curr_a_index
        ) {
            while (curr_b_to_c_before_a < curr_b_to_c &&
                cIndices[curr_b_to_c_before_a] < curr_a_index
            ) {
                curr_b_to_c_before_a += 1
            }
        } else if (curr_b_to_c_before_a > 0 &&
            cIndices[curr_b_to_c_before_a - 1] > curr_a_index
        ) {
            while (curr_b_to_c_before_a > 0 &&
                cIndices[curr_b_to_c_before_a - 1] > curr_a_index
            ) {
                curr_b_to_c_before_a -= 1
            }
        }

        val prev_a_stop_moves_spent = a_stop_moves_spent - 1
        val curr_b_to_c_after_a = curr_b_to_c - curr_b_to_c_before_a
        val new_b_after = prev_a_stop_moves_spent - curr_b_to_c_after_a
        val b_after = old_b_after_if_all_c_are_b[curr_a_index] + new_b_after
        curr_score -= b_after.toLong()
        curr_score += old_a_before[curr_a_index].toLong()

        prev_c_stop = c_stop
        c_stop = get_c_stop_by_moves_remain(movesRemain)
        c_stop_moves_spent = max_c_stop - c_stop

        require(c_stop - prev_c_stop in listOf(0, 1))
        if (c_stop - prev_c_stop == 1) {
            val prev_c_index = cIndices[prev_c_stop]
            val curr_a_to_b = a_n - a_stop
            if (curr_a_to_b_after_c < curr_a_to_b &&
                aIndices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index
            ) {
                while (curr_a_to_b_after_c < curr_a_to_b &&
                    aIndices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index
                ) {
                    curr_a_to_b_after_c += 1
                }
            } else if (curr_a_to_b_after_c > 0 &&
                aIndices[a_n - curr_a_to_b_after_c] < prev_c_index
            ) {
                while (curr_a_to_b_after_c > 0 &&
                    aIndices[a_n - curr_a_to_b_after_c] < prev_c_index
                ) {
                    curr_a_to_b_after_c -= 1
                }
            }

            val a_to_b_before = curr_a_to_b - curr_a_to_b_after_c
            val curr_a_before = old_a_before[prev_c_index] - a_to_b_before
            curr_score -= curr_a_before.toLong()
        }

        if (curr_score > bestScore) {
            bestScore = curr_score
        }
    }

    return bestScore
}

fun getCurrS(
    sArr: CharArray,
    aIndices: IntArray,
    a_stop: Int,
    cIndices: IntArray,
    c_stop: Int
): CharArray {
    val s = sArr.copyOf()
    for (i_i_a in 0 until a_stop) {
        val i_a = aIndices[i_i_a]
        s[i_a] = _A
    }
    for (i_i_a in a_stop until aIndices.size) {
        val i_a = aIndices[i_i_a]
        s[i_a] = _B
    }
    for (i_i_c in 0 until c_stop) {
        val i_c = cIndices[i_i_c]
        s[i_c] = _C
    }
    for (i_i_c in c_stop until cIndices.size) {
        val i_c = cIndices[i_i_c]
        s[i_c] = _B
    }
    return s
}

fun getCurrScoreSlowWay(sArr: CharArray): Long {
    var curr_score = 0L
    var a_accumulated = 0L
    for (ch in sArr) {
        when (ch) {
            _A -> a_accumulated += 1
            _B -> curr_score += a_accumulated
        }
    }
    return curr_score
}

fun computeABefore(sArr: CharArray): IntArray {
    val result = IntArray(sArr.size)
    var acc = 0
    for (i in sArr.indices) {
        acc += if (sArr[i] == _A) 1 else 0
        result[i] = acc
    }
    val shifted = IntArray(sArr.size)
    shifted[0] = 0
    for (i in 1 until sArr.size) {
        shifted[i] = result[i - 1]
    }
    return shifted
}

fun computeBAfter(s: String): IntArray {
    val n = s.length
    val revAccum = IntArray(n)
    var acc = 0
    for (i in n - 1 downTo 0) {
        acc += if (s[i] == _B) 1 else 0
        revAccum[i] = acc
    }
    val result = IntArray(n)
    for (i in 0 until n) {
        result[i] = revAccum[i]
    }
    val shifted = IntArray(n)
    for (i in 0 until n - 1) {
        shifted[i] = result[i + 1]
    }
    shifted[n - 1] = 0
    return shifted
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val _A = 'a'
private const val _B = 'b'
private const val _C = 'c'

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val n = st.nextToken().toInt()
    val k = st.nextToken().toInt()
    val s = reader.readLine()
    val t = reader.readLine()
    val result = find_best_score_can_make(s, t, moves_n = k)
    println(result)
}

fun find_best_score_can_make(sInput: String, t: String, moves_n: Int): Long {
    require(t.length == 2)
    if (t[0] == t[1]) {
        val tChar = t[0]
        var tCharCount = sInput.count { it == tChar }
        tCharCount += moves_n
        if (tCharCount > sInput.length) {
            tCharCount = sInput.length
        }
        return tCharCount.toLong() * (tCharCount - 1).toLong() / 2L
    }

    val sMapped = sInput.map { ch ->
        if (ch == t[0]) _A
        else if (ch == t[1]) _B
        else _C
    }.joinToString("")

    val (a_indices, b_indices, c_indices) = _compute_abc_indices(sMapped)

    var best_score = Long.MIN_VALUE

    val max_c_start = minOf(c_indices.size, moves_n)
    for (c_start in 0..max_c_start) {
        val c_start_moves_spent = c_start
        var moves_spent = c_start_moves_spent
        var moves_remain = moves_n - moves_spent
        require(moves_remain >= 0)

        val max_b_start = minOf(b_indices.size, moves_remain)
        for (b_start in 0..max_b_start) {
            val b_start_moves_spent = b_start
            moves_spent = c_start_moves_spent + b_start_moves_spent
            moves_remain = moves_n - moves_spent
            require(moves_remain >= 0)

            val new_s = sMapped.toCharArray()
            for (i_i_c in 0 until c_start) {
                val i_c = c_indices[i_i_c]
                new_s[i_c] = _A
            }
            for (i_i_b in 0 until b_start) {
                val i_b = b_indices[i_i_b]
                new_s[i_b] = _A
            }

            val curr_best_score = _find_best_score_can_make_with_fixed_starts(new_s, moves_remain)
            if (curr_best_score > best_score) {
                best_score = curr_best_score
            }
        }
    }

    return best_score
}

fun _compute_abc_indices(s: String): Triple<IntArray, IntArray, IntArray> {
    val aList = ArrayList<Int>()
    val bList = ArrayList<Int>()
    val cList = ArrayList<Int>()
    s.forEachIndexed { i, ch ->
        when (ch) {
            _A -> aList.add(i)
            _B -> bList.add(i)
            else -> {
                require(ch == _C)
                cList.add(i)
            }
        }
    }
    return Triple(aList.toIntArray(), bList.toIntArray(), cList.toIntArray())
}

fun _find_best_score_can_make_with_fixed_starts(sInput: CharArray, moves_n: Int): Long {
    val s = sInput.copyOf()

    var best_score = Long.MIN_VALUE

    val (a_indices, b_indices, c_indices) = _compute_abc_indices(String(s))

    val a_n = a_indices.size
    val c_n = c_indices.size

    val max_a_stop = a_indices.size
    val max_c_stop = c_indices.size

    fun get_c_stop_by_moves_remain(moves_remain: Int): Int {
        var min_c_stop = max_c_stop - moves_remain
        if (min_c_stop < 0) {
            min_c_stop = 0
        }
        return min_c_stop
    }

    val first_c_stop = get_c_stop_by_moves_remain(moves_n)
    val new_s = _get_curr_s(s, a_indices, max_a_stop, c_indices, first_c_stop)
    var curr_score = _get_curr_score_slow_way(new_s)

    if (curr_score > best_score) {
        best_score = curr_score
    }

    val old_a_before = _compute_a_before(new_s)
    val old_b_after_if_all_c_are_b = _compute_b_after(String(new_s).replace(_C, _B))

    var curr_b_to_c_before_a = 0
    var curr_a_to_b_after_c = 0

    var prev_c_stop: Int? = null
    var c_stop = first_c_stop
    var c_stop_moves_spent = max_c_stop - c_stop

    var min_a_stop = max_a_stop - moves_n
    min_a_stop = maxOf(min_a_stop, 0)
    for (a_stop in max_a_stop - 1 downTo min_a_stop) {
        val a_stop_moves_spent = max_a_stop - a_stop
        val moves_spent = a_stop_moves_spent
        val moves_remain = moves_n - moves_spent
        require(moves_remain >= 0)

        require(a_stop_moves_spent > 0)

        val curr_a_index = a_indices[a_stop]
        val curr_b_to_c = c_stop
        if (curr_b_to_c_before_a < curr_b_to_c &&
            c_indices[curr_b_to_c_before_a] < curr_a_index
        ) {
            while (curr_b_to_c_before_a < curr_b_to_c &&
                c_indices[curr_b_to_c_before_a] < curr_a_index
            ) {
                curr_b_to_c_before_a += 1
            }
        } else if (curr_b_to_c_before_a > 0 &&
            c_indices[curr_b_to_c_before_a - 1] > curr_a_index
        ) {
            while (curr_b_to_c_before_a > 0 &&
                c_indices[curr_b_to_c_before_a - 1] > curr_a_index
            ) {
                curr_b_to_c_before_a -= 1
            }
        }

        val prev_a_stop_moves_spent = a_stop_moves_spent - 1
        val curr_b_to_c_after_a = curr_b_to_c - curr_b_to_c_before_a
        val new_b_after = prev_a_stop_moves_spent - curr_b_to_c_after_a
        val b_after = old_b_after_if_all_c_are_b[curr_a_index] + new_b_after
        curr_score -= b_after.toLong()
        curr_score += old_a_before[curr_a_index].toLong()

        prev_c_stop = c_stop
        c_stop = get_c_stop_by_moves_remain(moves_remain)
        c_stop_moves_spent = max_c_stop - c_stop

        require(c_stop - prev_c_stop in 0..1)
        if (c_stop - prev_c_stop == 1) {
            val prev_c_index = c_indices[prev_c_stop]
            val curr_a_to_b = a_n - a_stop
            if (curr_a_to_b_after_c < curr_a_to_b &&
                a_indices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index
            ) {
                while (curr_a_to_b_after_c < curr_a_to_b &&
                    a_indices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index
                ) {
                    curr_a_to_b_after_c += 1
                }
            } else if (curr_a_to_b_after_c > 0 &&
                a_indices[a_n - curr_a_to_b_after_c] < prev_c_index
            ) {
                while (curr_a_to_b_after_c > 0 &&
                    a_indices[a_n - curr_a_to_b_after_c] < prev_c_index
                ) {
                    curr_a_to_b_after_c -= 1
                }
            }

            val a_to_b_before = curr_a_to_b - curr_a_to_b_after_c
            val curr_a_before = old_a_before[prev_c_index] - a_to_b_before
            curr_score -= curr_a_before.toLong()
        }

        if (curr_score > best_score) {
            best_score = curr_score
        }
    }

    return best_score
}

fun _get_curr_s(
    sInput: CharArray,
    a_indices: IntArray,
    a_stop: Int,
    c_indices: IntArray,
    c_stop: Int
): CharArray {
    val s = sInput.copyOf()
